function cdLong(t){const d=Math.max(0,Math.round((t-nowMs())/1000)),dd=Math.floor(d/86400),h=Math.floor(d%86400/3600),m=Math.floor(d%3600/60),sc=d%60,p=n=>String(n).padStart(2,"0");return (dd?`${dd}d `:"")+`${p(h)}:${p(m)}:${p(sc)}`}
